"use client";

import { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase";
import Link from "next/link";
import styles from "./forum.module.css";
import stylesModal from "@/components/onboarding/onboarding.module.css"; // Reuse modal

type Post = {
    id: string;
    title: string;
    content: string;
    category: string;
    likes_count: number;
    created_at: string;
    user_id: string;
    comments: { count: number }[]; // Add relation type
};

// ... in fetchPosts ...
// Removed incorrect comments


// Removed incorrect comments


const CATEGORIES = ["All", "General", "Accommodation", "Visa", "Nightlife", "Travel"];

export default function ForumPage() {
    const supabase = createClient();
    const [posts, setPosts] = useState<Post[]>([]);
    const [activeCategory, setActiveCategory] = useState("All");
    const [loading, setLoading] = useState(true);

    // New Post Modal
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [newPost, setNewPost] = useState({ title: '', content: '', category: 'General' });

    useEffect(() => {
        fetchPosts();
    }, [activeCategory]);

    const fetchPosts = async () => {
        setLoading(true);
        let query = supabase
            .from('posts')
            .select('*, comments(count)')
            .order('created_at', { ascending: false });

        if (activeCategory !== "All") {
            query = query.eq('category', activeCategory);
        }

        const { data, error } = await query;
        if (data) setPosts(data as any);
        setLoading(false);
    };

    const handleCreatePost = async () => {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        if (!newPost.title || !newPost.content) return;

        const { error } = await supabase
            .from('posts')
            .insert({
                user_id: user.id,
                title: newPost.title,
                content: newPost.content,
                category: newPost.category
            });

        if (error) {
            alert("Error posting: " + error.message);
        } else {
            setIsModalOpen(false);
            setNewPost({ title: '', content: '', category: 'General' });
            fetchPosts();
        }
    };

    return (
        <div className={styles.container}>
            {/* Sidebar */}
            <div className={styles.sidebar}>
                <button className={styles.newPostBtn} onClick={() => setIsModalOpen(true)}>
                    ✍️ Ask a Question
                </button>

                <div className={styles.filterGroup}>
                    <div className={styles.filterTitle}>Topics</div>
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat}
                            className={`${styles.filterBtn} ${activeCategory === cat ? styles.filterBtnActive : ''}`}
                            onClick={() => setActiveCategory(cat)}
                        >
                            {cat === "All" ? "🔥 Trending" : `# ${cat}`}
                        </button>
                    ))}
                </div>
            </div>

            {/* Feed */}
            <div className={styles.feed}>
                {loading ? (
                    <p style={{ padding: '2rem', textAlign: 'center' }}>Loading discussions...</p>
                ) : posts.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '3rem', border: '1px dashed var(--border)', borderRadius: '1rem' }}>
                        <h3>No discussions yet 🦗</h3>
                        <p style={{ color: 'var(--secondary-foreground)' }}>Be the first to ask a question in this category!</p>
                    </div>
                ) : (
                    posts.map(post => (
                        <Link href={`/dashboard/forum/${post.id}`} key={post.id} className={styles.postCard}>
                            <div className={styles.postHeader}>
                                <span className={styles.postCategory}>{post.category}</span>
                                <span style={{ fontSize: '0.8rem', color: 'var(--secondary-foreground)' }}>
                                    {new Date(post.created_at).toLocaleDateString()}
                                </span>
                            </div>
                            <h3 className={styles.postTitle}>{post.title}</h3>
                            <p className={styles.postPreview}>{post.content}</p>
                            <div className={styles.postMeta}>
                                <span>👤 Student</span>
                                <span>💬 {post.comments && post.comments[0] ? post.comments[0].count : 0} comments</span>
                                <span>❤️ {post.likes_count}</span>
                            </div>
                        </Link>
                    ))
                )}
            </div>

            {/* CREATE POST MODAL */}
            {isModalOpen && (
                <div className={stylesModal.overlay}>
                    <div className={stylesModal.modal}>
                        <div style={{ padding: '1.5rem', borderBottom: '1px solid var(--border)' }}>
                            <h2 style={{ fontSize: '1.25rem' }}>Ask the Community</h2>
                        </div>
                        <div style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                            <div>
                                <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Title</label>
                                <input
                                    className={styles.input}
                                    placeholder="e.g. How to find accommodation in Warsaw?"
                                    value={newPost.title}
                                    onChange={e => setNewPost({ ...newPost, title: e.target.value })}
                                />
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Category</label>
                                <select
                                    className={styles.select}
                                    value={newPost.category}
                                    onChange={e => setNewPost({ ...newPost, category: e.target.value })}
                                >
                                    {CATEGORIES.filter(c => c !== "All").map(c => (
                                        <option key={c} value={c}>{c}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Details</label>
                                <textarea
                                    className={styles.textarea}
                                    placeholder="Describe your question in detail..."
                                    value={newPost.content}
                                    onChange={e => setNewPost({ ...newPost, content: e.target.value })}
                                />
                            </div>

                            <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                                <button
                                    className={stylesModal.backBtn}
                                    onClick={() => setIsModalOpen(false)}
                                    style={{ flex: 1, border: '1px solid var(--border)' }}
                                >
                                    Cancel
                                </button>
                                <button
                                    className={stylesModal.nextBtn}
                                    onClick={handleCreatePost}
                                    style={{ flex: 1 }}
                                >
                                    Post Question
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
